// The runtime's pure helpers: no DOM, no top-level await, so `node --test` can import them
// (src/lib.test.ts). runtime.ts imports them as './lib.js', built to site/lib.js.
import type { PluginModule, TilrPlugin } from './types.ts'

/** `inject` as cordis accepts it: an array, an object, or inherited on a class. */
export function injects(plugin: TilrPlugin | undefined): string[] {
  const inject = plugin?.inject
  if (!inject) return []
  if (Array.isArray(inject)) return [...inject]
  const names: string[] = []
  for (let o: object | null = inject; o && o !== Object.prototype; o = Object.getPrototypeOf(o)) names.push(...Object.keys(o))
  return [...new Set(names)]
}

/** The module's default export is something cordis can start: a function or class, or an
 *  object with `apply`. Checked before the old instance is stopped. */
export function hasDefault(module: unknown): module is PluginModule {
  if (typeof module !== 'object' || module === null || !('default' in module)) return false
  const plugin = module.default
  return typeof plugin === 'function' || (typeof plugin === 'object' && plugin !== null && 'apply' in plugin && typeof plugin.apply === 'function')
}

/** The export `@tilr-dev/plugin/build` appends to a plugin it builds: the package.json version
 *  of the plugin and the `@tilr-dev/plugin` version it was built with. */
export const BUILD_STAMP = '__tilrBuild'

/** The default `version` and `api` of a built plugin, from its build's stamp
 *  (`export const __tilrBuild = { version: '1.2.0', api: '^0.1.14' }`), filled into the default
 *  export where it leaves them unset: a plugin's own `version` / `api` (or a class's static ones)
 *  always win. A module without a stamp (an in-tree plugin, one built by hand) is left as is.
 *  `definePlugin()` runs in the page's tilr.js, where the plugin's build constants are not
 *  defined: the stamp is how its build reaches the runtime, for object and class plugins alike. */
export function stampBuild(module: PluginModule): void {
  if (!(BUILD_STAMP in module)) return
  const stamp = module[BUILD_STAMP]
  if (typeof stamp !== 'object' || stamp === null) return
  const plugin = module.default
  for (const key of ['version', 'api'] as const) {
    const value = key in stamp ? (stamp as Record<typeof key, unknown>)[key] : undefined
    if (typeof value !== 'string' || plugin[key] !== undefined) continue
    try { Object.defineProperty(plugin, key, { value, configurable: true, enumerable: true, writable: true }) } catch {}
  }
}

/** A thrown value as an Error, so the panel and the log can show its message. */
export function asError(error: unknown): Error {
  return error instanceof Error ? error : new Error(String(error))
}

/** The plugin names in plugins.json (`{ "plugins": [...] }`). */
export function pluginNames(json: unknown): string[] {
  if (typeof json === 'object' && json !== null && 'plugins' in json && Array.isArray(json.plugins)) {
    return json.plugins.filter((name): name is string => typeof name === 'string')
  }
  throw new Error('plugins.json: expected { "plugins": [names] }')
}

// Semver, just what plugin metadata needs (`api`, `requires`), without a dependency.
// Pre-release and build tags are parsed and then ignored: `1.2.3-beta` compares as 1.2.3, so a
// pre-release satisfies `^1.2.3` and `>=1.2.3` (npm would say no). Not supported properly.

/** major, minor, patch. */
export type Version = [number, number, number]

const TAG = String.raw`(?:-[0-9A-Za-z.-]+)?(?:\+[0-9A-Za-z.-]+)?`
const VERSION = new RegExp(String.raw`^v?(\d+)\.(\d+)\.(\d+)${TAG}$`)
// One comparator of a range: an operator and a version that may be partial (`^1`, `~1.2`) or
// have wildcards (`1.x`, `*`).
const COMPARATOR = new RegExp(String.raw`^(<=|>=|<|>|=|\^|~)?v?(\d+|[xX*])(?:\.(\d+|[xX*]))?(?:\.(\d+|[xX*]))?${TAG}$`)

/** `'1.2.3'` (also `v1.2.3`, `1.2.3-beta`) → `[1, 2, 3]`; anything else → null. */
export function parseVersion(version: string): Version | null {
  const match = typeof version === 'string' ? VERSION.exec(version.trim()) : null
  return match ? [Number(match[1]), Number(match[2]), Number(match[3])] : null
}

function compare(a: Version, b: Version): number {
  return a[0] - b[0] || a[1] - b[1] || a[2] - b[2]
}

/** The given parts with the one at `i` incremented, the rest zeroed: bump([1, 2], 1) → 1.3.0. */
function bump(parts: number[], i: number): Version {
  const out: Version = [0, 0, 0]
  for (let k = 0; k < i; k++) out[k] = parts[k]
  out[i] = parts[i] + 1
  return out
}

/** One comparator as a test, or null when it does not parse. A partial version stands for the
 *  versions it covers: `1.2` is [1.2.0, 1.3.0), so `>1.2` is >=1.3.0 and `<=1.2` is <1.3.0. */
function comparator(token: string): ((v: Version) => boolean) | null {
  const match = COMPARATOR.exec(token)
  if (!match) return null
  const op = match[1] ?? '='
  // The parts given before the first wildcard or the end: `1.x.3` is `1`.
  const parts: number[] = []
  for (const part of match.slice(2, 5)) {
    if (part === undefined || !/^\d+$/.test(part)) break
    parts.push(Number(part))
  }
  if (!parts.length) return op === '<' || op === '>' ? () => false : () => true
  const low: Version = [parts[0], parts[1] ?? 0, parts[2] ?? 0]
  const high = bump(parts, parts.length - 1)
  const within = (top: Version) => (v: Version) => compare(v, low) >= 0 && compare(v, top) < 0
  switch (op) {
    case '=': return within(high)
    case '>=': return v => compare(v, low) >= 0
    case '>': return v => compare(v, high) >= 0
    case '<': return v => compare(v, low) < 0
    case '<=': return v => compare(v, high) < 0
    // ~1.2.3, ~1.2 → <1.3.0; ~1 → <2.0.0
    case '~': return within(bump(parts, parts.length > 1 ? 1 : 0))
    // ^ bumps the first non-zero part given, or the last one if all are zero:
    // ^1.2.3 → <2.0.0, ^0.2.3 → <0.3.0, ^0.0.3 → <0.0.4, ^0 → <1.0.0, ^0.0 → <0.1.0
    default: {
      const first = parts.findIndex(part => part !== 0)
      return within(bump(parts, first === -1 ? parts.length - 1 : first))
    }
  }
}

/**
 * Whether `version` is in `range`, npm style: `1.2.3` (exact), `^1.2.3`, `~1.2.3`, `>=1.2.3`,
 * `>`, `<`, `<=`, partials (`^1`, `1.2`, `1.x`), `*` or `''` (anything), comparators separated
 * by spaces (all must hold: `>=1.2.0 <2.0.0`) and alternatives separated by `||`.
 * An invalid version or range is false: the caller reports it as a mismatch.
 */
export function satisfies(version: string, range: string): boolean {
  const v = parseVersion(version)
  if (!v || typeof range !== 'string') return false
  // `>= 1.2.3` is `>=1.2.3`.
  const alternatives = range.replace(/(<=|>=|<|>|=|\^|~)\s+/g, '$1').split('||').map(alternative => {
    const tests = alternative.trim().split(/\s+/).filter(Boolean).map(comparator)
    return tests.every(test => test !== null) ? tests : null
  })
  if (alternatives.some(tests => tests === null)) return false
  return alternatives.some(tests => tests?.every(test => test(v)))
}
